#include "runtime/interpreter.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
int main(){using namespace penta;unsigned checks=0,failures=0;const auto directory=std::filesystem::temp_directory_path()/("penta-petsc-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(directory);runtime::ExecutionOptions options;options.dataDirectory=directory;options.odeCacheDirectory=directory/"cache/odes";auto run=[&](const std::string& source){++checks;const auto result=runtime::execute(source,{},options);if(!result.ok()){++failures;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';}};
run("record s=petscsolve([4,1;1,3],[1,2]);assert(s.converged);assert(norm(s.x-[1/11;7/11],\"fro\")<1e-10);assert(s.residual_norm<1e-10);record z=petscsolve(sparse([4,1;1,3]),[1,2],options(preconditioner=\"ilu\"));assert(z.converged);assert(norm(z.x-s.x,\"fro\")<1e-10);");
run("native function [real first,real second] f(real x,real y,real target){return x*x+y-target,x+y*y-target;}record a=petscroot(f,[1,1],options(parameters=options(target=3.0),atol=1e-12));record b=petscroot(f,[1,1],options(parameters=options(target=4.0),atol=1e-12));assert(a.converged&&b.converged);assert(a.jacobian_evaluations>0);assert(a.cache_key==b.cache_key);assert(b.cache_hit);assert(norm(a.x-(sqrt(13)-1)/2,\"fro\")<1e-10);");
run("function integer monitor(matrix x,record info,string state){return state==\"iter\";}native function real f(real x){return x*x-2;}record a=petscroot(f,10.0,options(OutputFcn=monitor));assert(a.stopped);assert(a.converged==0);assert(a.status==\"user_stopped\");");
run("native function real reaction(real u,real t,real x){return -2*u;}native function real initial(real t,real x){return cos(3.14159265358979323846*x);}matrix x=linspace(0,1,17);record a=pdeimplicit(reaction,x,initial,options(t1=.02,time_step=.01,sample_step=.01,adaptive=0));record b=pdeimplicit(reaction,x,initial,options(t1=.02,time_step=.01,sample_step=.01,adaptive=0,linear_backend=\"petsc_gmres\"));assert(norm(a.values-b.values,\"fro\")<1e-7);assert(b.linear_iterations>0);assert(b.linear_backend==\"petsc_gmres\");record c=pdeimplicit(reaction,x,initial,options(t1=.02,time_step=.01,sample_step=.01,adaptive=0,linear_backend=\"petsc_ilu\"));assert(norm(a.values-c.values,\"fro\")<1e-7);");
run("native function real reaction(real u,real t,real x,real y,real z){return -2*u;}native function real initial(real t,real x,real y,real z){return x+y;}record mesh=meshplane([0,1],[0,1],options(nx=4,ny=4));record a=pdeimplicit(reaction,mesh,initial,options(t1=.02,time_step=.01,sample_step=.01,adaptive=0));record b=pdeimplicit(reaction,mesh,initial,options(t1=.02,time_step=.01,sample_step=.01,adaptive=0,linear_backend=\"petsc_ilu\"));assert(norm(a.values-b.values,\"fro\")<1e-7);assert(b.linear_iterations>0);");
#ifdef PENTA_SOURCE_DIR
for(const auto* name:{"sparse-poisson-ksp.p","cached-native-snes-root.p","implicit-surface-pde.p"}){std::ifstream input(std::filesystem::path(PENTA_SOURCE_DIR)/"examples/native-petsc"/name);const std::string source((std::istreambuf_iterator<char>(input)),{});run(source);}
#endif
std::error_code ignored;std::filesystem::remove_all(directory,ignored);std::cout<<checks<<" PETSc language checks, "<<failures<<" failures\n";return failures?1:0;}
